import React, { useState, useEffect } from 'react';
import { Chart } from 'react-google-charts';
import axios from 'axios';
import './Visualization.css';

function Visualization() {
  const [columns, setColumns] = useState([]);
  const [selectedX, setSelectedX] = useState('age');
  const [selectedY, setSelectedY] = useState('bmi');
  const [chartType, setChartType] = useState('ScatterChart');
  const [data, setData] = useState([]);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    const fetchColumns = async () => {
      try {
        const response = await axios.get('http://localhost:8000/data/columns');
        setColumns(response.data.columns);
      } catch (error) {
        console.error('Error fetching columns:', error);
      }
    };
    fetchColumns();
  }, []);

  const generateChart = async () => {
    setIsLoading(true);
    try {
      const response = await axios.get('http://localhost:8000/data/sample', {
        params: { x: selectedX, y: selectedY }
      });
      const chartData = [
        [selectedX, selectedY],
        ...response.data.map(item => [item[selectedX], item[selectedY]])
      ];
      setData(chartData);
    } catch (error) {
      console.error('Error generating chart:', error);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="visualization-container">
      <h2>Data Visualization</h2>
      
      <div className="controls">
        <div className="control-group">
          <label>X-Axis:</label>
          <select value={selectedX} onChange={(e) => setSelectedX(e.target.value)}>
            {columns.filter(c => c !== 'diabetes').map(col => (
              <option key={col} value={col}>{col}</option>
            ))}
          </select>
        </div>

        <div className="control-group">
          <label>Y-Axis:</label>
          <select value={selectedY} onChange={(e) => setSelectedY(e.target.value)}>
            {columns.filter(c => c !== 'diabetes').map(col => (
              <option key={col} value={col}>{col}</option>
            ))}
          </select>
        </div>

        <div className="control-group">
          <label>Chart Type:</label>
          <select value={chartType} onChange={(e) => setChartType(e.target.value)}>
            <option value="ScatterChart">Scatter Chart</option>
            <option value="LineChart">Line Chart</option>
            <option value="BarChart">Bar Chart</option>
          </select>
        </div>

        <button onClick={generateChart} disabled={isLoading}>
          {isLoading ? 'Generating...' : 'Generate Chart'}
        </button>
      </div>

      {data.length > 0 && (
        <div className="chart-container">
          <Chart
            chartType={chartType}
            width="100%"
            height="400px"
            data={data}
            options={{
              title: `${selectedY} vs ${selectedX}`,
              hAxis: { title: selectedX },
              vAxis: { title: selectedY },
            }}
          />
        </div>
      )}
    </div>
  );
}

export default Visualization;
